function consecutiveRuns(n: number): number {
  while (n % 2 === 0) n /= 2;
  let ways = 1;
  for (let p = 3; p * p <= n; p += 2) {
    let e = 0;
    while (n % p === 0) { n /= p; e++; }
    ways *= e + 1;
  }
  if (n > 1) ways *= 2; // one prime factor left over
  return ways;
}

